// Fail-closed QNN component probe using real inputs from the official FP32 chain.
#include <chrono>
#include <cmath>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string>
#include <sys/resource.h>
#include <unordered_map>
#include <vector>
#include "onnxruntime_cxx_api.h"
namespace {
using Clock=std::chrono::steady_clock;
struct Args{std::string component,model,inputs,output,backend,profile;int runs=2;};
Args Parse(int n,char**v){Args a;auto take=[&](int&i){if(++i>=n)throw std::runtime_error("missing value");return std::string(v[i]);};for(int i=1;i<n;++i){std::string k=v[i];if(k=="--component")a.component=take(i);else if(k=="--model")a.model=take(i);else if(k=="--inputs")a.inputs=take(i);else if(k=="--output")a.output=take(i);else if(k=="--backend")a.backend=take(i);else if(k=="--profile-prefix")a.profile=take(i);else if(k=="--runs")a.runs=std::stoi(take(i));else throw std::runtime_error("unknown argument "+k);}if(a.component.empty()||a.model.empty()||a.inputs.empty()||a.output.empty()||a.backend.empty()||a.profile.empty()||a.runs<1)throw std::runtime_error("missing argument");return a;}
template<class T>std::vector<T>Read(const std::filesystem::path&p,size_t n){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f||size_t(f.tellg())!=n*sizeof(T))throw std::runtime_error("input size mismatch: "+p.string());f.seekg(0);std::vector<T>x(n);f.read(reinterpret_cast<char*>(x.data()),n*sizeof(T));if(!f)throw std::runtime_error("input read failed");return x;}
void Write(const std::string&p,const float*x,size_t n){std::ofstream f(p,std::ios::binary|std::ios::trunc);f.write(reinterpret_cast<const char*>(x),n*sizeof(float));if(!f)throw std::runtime_error("output write failed");}
double Sec(Clock::time_point t){return std::chrono::duration<double>(Clock::now()-t).count();}long Rss(){rusage u{};return getrusage(RUSAGE_SELF,&u)?-1:u.ru_maxrss;}
template<class T>Ort::Value Tensor(std::vector<T>&v,std::vector<int64_t>s,Ort::MemoryInfo&m){return Ort::Value::CreateTensor<T>(m,v.data(),v.size(),s.data(),s.size());}
}
int main(int argc,char**argv){try{auto a=Parse(argc,argv);Ort::Env env(ORT_LOGGING_LEVEL_INFO,"0011-component-probe");Ort::SessionOptions o;o.SetIntraOpNumThreads(1);o.SetInterOpNumThreads(1);o.SetExecutionMode(ExecutionMode::ORT_SEQUENTIAL);o.SetGraphOptimizationLevel(GraphOptimizationLevel::ORT_ENABLE_ALL);o.AddConfigEntry("session.disable_cpu_ep_fallback","1");o.EnableProfiling(a.profile.c_str());const std::unordered_map<std::string,std::string>po={{"backend_path",a.backend},{"profiling_level","detailed"},{"profiling_file_path",a.profile+".qnn.csv"},{"offload_graph_io_quantization","0"},{"htp_performance_mode","burst"},{"soc_model","43"}};o.AppendExecutionProvider("QNN",po);auto t=Clock::now();Ort::Session s(env,a.model.c_str(),o);double create=Sec(t);auto mem=Ort::MemoryInfo::CreateCpu(OrtArenaAllocator,OrtMemTypeDefault);std::vector<const char*>names;std::vector<Ort::Value>values;std::vector<int64_t>ids;std::vector<float>mask,dp,ttl,latent,emb,lmask,current,total;
auto root=std::filesystem::path(a.inputs);
if(a.component=="duration_predictor"){ids=Read<int64_t>(root/"text_ids.raw",239);dp=Read<float>(root/"style_dp.raw",128);mask=Read<float>(root/"text_mask.raw",239);names={"text_ids","style_dp","text_mask"};values.push_back(Tensor(ids,{1,239},mem));values.push_back(Tensor(dp,{1,8,16},mem));values.push_back(Tensor(mask,{1,1,239},mem));}
else if(a.component=="text_encoder"){ids=Read<int64_t>(root/"text_ids.raw",239);ttl=Read<float>(root/"style_ttl.raw",12800);mask=Read<float>(root/"text_mask.raw",239);names={"text_ids","style_ttl","text_mask"};values.push_back(Tensor(ids,{1,239},mem));values.push_back(Tensor(ttl,{1,50,256},mem));values.push_back(Tensor(mask,{1,1,239},mem));}
else if(a.component=="vector_estimator"){latent=Read<float>(root/"step0_noisy_latent.raw",34272);emb=Read<float>(root/"text_emb.raw",61184);ttl=Read<float>(root/"style_ttl.raw",12800);lmask=Read<float>(root/"latent_mask.raw",238);mask=Read<float>(root/"text_mask.raw",239);current=Read<float>(root/"current_step.raw",1);total=Read<float>(root/"total_step.raw",1);names={"noisy_latent","text_emb","style_ttl","latent_mask","text_mask","current_step","total_step"};values.push_back(Tensor(latent,{1,144,238},mem));values.push_back(Tensor(emb,{1,256,239},mem));values.push_back(Tensor(ttl,{1,50,256},mem));values.push_back(Tensor(lmask,{1,1,238},mem));values.push_back(Tensor(mask,{1,1,239},mem));values.push_back(Tensor(current,{1},mem));values.push_back(Tensor(total,{1},mem));}
else if(a.component=="vocoder"){latent=Read<float>(root/"final_latent.raw",34272);names={"latent"};values.push_back(Tensor(latent,{1,144,238},mem));}else throw std::runtime_error("unknown component");
Ort::AllocatorWithDefaultOptions alloc;auto outname=s.GetOutputNameAllocated(0,alloc);const char*outs[]={outname.get()};std::vector<Ort::Value>r;std::vector<double>times;for(int i=0;i<a.runs;++i){t=Clock::now();r=s.Run(Ort::RunOptions{nullptr},names.data(),values.data(),values.size(),outs,1);times.push_back(Sec(t));}auto info=r[0].GetTensorTypeAndShapeInfo();size_t count=info.GetElementCount();const float*x=r[0].GetTensorData<float>();for(size_t i=0;i<count;++i)if(!std::isfinite(x[i]))throw std::runtime_error("nonfinite output");size_t expected=a.component=="duration_predictor"?1:a.component=="text_encoder"?61184:a.component=="vector_estimator"?34272:731136;if(count!=expected)throw std::runtime_error("output count mismatch");Write(a.output,x,count);auto profile=s.EndProfilingAllocated(alloc);std::cout<<"{\n  \"result\": \"passed\",\n  \"component\": \""<<a.component<<"\",\n  \"provider\": \"QNNExecutionProvider\",\n  \"cpu_fallback_disabled\": true,\n  \"source_assets\": \"official FP32 ONNX inference/export assets\",\n  \"arithmetic_claim\": \"not established; FP32 source does not prove FP32 HTP arithmetic\",\n  \"session_create_seconds\": "<<create<<",\n  \"run_seconds\": [";for(size_t i=0;i<times.size();++i){if(i)std::cout<<",";std::cout<<times[i];}std::cout<<"],\n  \"output_elements\": "<<count<<",\n  \"max_rss_kb\": "<<Rss()<<",\n  \"profile_path\": \""<<profile.get()<<"\"\n}\n";return 0;}catch(const Ort::Exception&e){std::cerr<<"ORT error "<<e.GetOrtErrorCode()<<": "<<e.what()<<"\n";return 2;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<"\n";return 3;}}
